{
  "verses": [
    {
      "chapter": 35,
      "verse": 4,
      "text_ar": "الزنج الذين يقفون عند الصلوات من أجل أبيك آدم؟"
    },
    {
      "chapter": 36,
      "verse": 1,
      "text_ar": "وأخبر شيث أمه أنهما الشمس والقمر وهما يخران ساجدين ويصليان نيابة عن أبي آدم. فقالت له حواء:"
    },
    {
      "chapter": 36,
      "verse": 2,
      "text_ar": "وأين نورهم ولماذا اكتسيا هذا المظهر الأسود؟"
    },
    {
      "chapter": 36,
      "verse": 3,
      "text_ar": "فأجابها شيث: لم يفارقهم النور، ولكن لا يقدران أن يضيئا أمام نور الكون، أب الأنوار؛ ولهذا السبب حُجب عنهما نورها."
    },
    {
      "chapter": 37,
      "verse": 1,
      "text_ar": "وبينما كان شيث يقول هذا لأمه، إذا بملاك ينفخ في البوق، ووقف كل الملائكة (الذين كانوا) على وجوههم، وصرخوا بصوت مهيب وقالوا: مبارك مجد الرب من"
    }
  ],
  "book_code": "APMO"
}
